def fn(x):
    # QWERTY layout in the order of the alphabet
    qwerty = "qwertyuiopasdfghjklzxcvbnm"
    alphabet = "abcdefghijklmnopqrstuvwxyz"

    # create mapping dictionaries for lower‑case and upper‑case letters
    lower_map = {alphabet[i]: qwerty[i] for i in range(26)}
    upper_map = {alphabet[i].upper(): qwerty[i].upper() for i in range(26)}

    # translate the input string preserving case
    result = []
    for ch in x:
        if ch.islower():
            result.append(lower_map.get(ch, ch))
